import{_ as e,o as n,c as i,a2 as m}from"./chunks/framework.DtFGJNng.js";const p=JSON.parse('{"title":"Filosofi Deuz","description":"","frontmatter":{},"headers":[],"relativePath":"filosofi.md","filePath":"filosofi.md","lastUpdated":1794565319000}'),r={name:"filosofi.md"};function t(u,a,s,k,d,o){return n(),i("div",null,[...a[0]||(a[0]=[m('<h1 id="filosofi-deuz" tabindex="-1">Filosofi Deuz <a class="header-anchor" href="#filosofi-deuz" aria-label="Permalink to &quot;Filosofi Deuz&quot;">​</a></h1><p>Deuz berawal dari satu pertanyaan di tim kami. Bagaimana AI bisa membantu di setiap tahap kerja agar kami bisa menghasilkan sesuatu lebih cepat, mengurangi pekerjaan ulang, dan tetap menjawab kebutuhan bisnis?</p><h2 id="enam-minggu-mencari-alur-yang-cocok" tabindex="-1">Enam minggu mencari alur yang cocok <a class="header-anchor" href="#enam-minggu-mencari-alur-yang-cocok" aria-label="Permalink to &quot;Enam minggu mencari alur yang cocok&quot;">​</a></h2><p>Kami mulai dari <em>The AI-native SDLC Playbook</em> Anthropic. Alur <code>intent.md</code> → <code>spec.md</code> → <code>plan.md</code> memberi kami gagasan awal yang menarik. Maksud bisnis ditulis, diterjemahkan menjadi spesifikasi, lalu dijabarkan menjadi rencana implementasi. Dokumen yang dihasilkan pada satu tahap menjadi acuan bagi orang dan agen AI di tahap berikutnya. <a href="https://claude.com/resources/articles/the-ai-native-sdlc-playbook" target="_blank" rel="noreferrer">The AI-native SDLC Playbook</a></p><p>Setelah berminggu-minggu mencoba, kami menemui jalan buntu. Saat alur itu dibawa ke pekerjaan sehari-hari, kami masih belum menemukan bentuk yang konsisten untuk tim kami. Apa yang perlu masuk ke tiap file? Seberapa rinci isinya? Format apa yang membantu pembaca berikutnya, dan kapan dokumen itu siap diserahkan? Pertanyaan-pertanyaan itu muncul kembali setiap kali kami mencoba format baru.</p><p>Kami lalu mencoba alur Kiro dengan <code>requirements.md</code>, <code>design.md</code>, dan <code>tasks.md</code>. Dari percobaan itu, kami mengambil gagasan penandaan dokumen dengan metadata dan cara memperlihatkan alur antardokumen. Keduanya menjadi dasar pengelolaan dokumen Deuz. Susunan dokumen dan isinya kami rancang sesuai pekerjaan tim kami. <a href="https://kiro.dev/docs/getting-started/first-project/" target="_blank" rel="noreferrer">Dokumentasi Kiro</a></p><p>Titik baliknya datang ketika kami menemukan OpenSpec. Awalnya kami belum melihat bagaimana <em>spec-driven development</em> bisa masuk ke cara kerja kami yang <em>business-driven</em>. Pekerjaan kami berangkat dari kebutuhan bisnis dan melibatkan beberapa tim dengan alur berbeda. Setelah mendalami konfigurasi OpenSpec, kami melihat bahwa skema, jenis dokumen, templat, dan ketergantungan antardokumen bisa disesuaikan. Itu memberi kami cara untuk berangkat dari kebutuhan bisnis, menerjemahkannya menjadi spesifikasi, lalu meneruskannya ke tiap peran sesuai alur tim. <a href="https://openspec.dev/" target="_blank" rel="noreferrer">OpenSpec</a> · <a href="https://github.com/Fission-AI/OpenSpec/blob/main/docs/customization.md" target="_blank" rel="noreferrer">Dokumentasi kustomisasi OpenSpec</a></p><p>Setelah enam minggu mencoba berbagai pendekatan, kami menemukan formulasi yang cocok untuk tim kami. Claude Code membentuk cara kami bekerja bersama agen AI, dengan kerangka 4D sebagai bagian dari pendekatan kami. Kiro menginspirasi cara kami mengelola dokumen dan melacak perkembangannya. OpenSpec memberi kami model spesifikasi dengan alur yang bisa disesuaikan.</p><h2 id="cara-deuz-bekerja" tabindex="-1">Cara Deuz bekerja <a class="header-anchor" href="#cara-deuz-bekerja" aria-label="Permalink to &quot;Cara Deuz bekerja&quot;">​</a></h2><ul><li><strong>Mulai dari kebutuhan bisnis.</strong> Proposal menjelaskan alasan dan tujuan pekerjaan. Spesifikasi menerjemahkannya menjadi perilaku yang bisa dipahami bersama dan diuji.</li><li><strong>Catat kesiapan sebelum serah terima.</strong> Setiap dokumen memiliki peran yang bertanggung jawab atas isinya. AI dapat membantu menyusun draf. Konfirmasi pemilik dokumen memberi tim berikutnya kepastian untuk mulai bekerja.</li><li><strong>Sesuaikan alur dengan pekerjaan.</strong> Tim dapat mengatur peran dan alur sesuai kebutuhannya. Setiap pekerjaan membawa dokumen yang relevan dengan area yang terdampak. Deuz mencatat status dan hubungan antardokumen di <a href="./manifest">manifest <code>.deuz.yaml</code></a>, sehingga tim bisa melihat dokumen mana yang siap dan apa yang masih ditunggu.</li></ul><h2 id="asal-nama-deuz" tabindex="-1">Asal nama Deuz <a class="header-anchor" href="#asal-nama-deuz" aria-label="Permalink to &quot;Asal nama Deuz&quot;">​</a></h2><p>Dalam cerita, <em>deus ex machina</em> adalah teknik plot ketika masalah yang tampak mustahil diselesaikan mendadak terurai karena munculnya tokoh, kekuatan, atau kejadian tak terduga dari luar alur. Istilah itu mengingatkan kami pada momen ketika fleksibilitas OpenSpec membuka jalan setelah berminggu-minggu mencoba merumuskan alur kerja kami. <a href="https://ahdictionary.com/word/search.html?q=deus+ex+machina" target="_blank" rel="noreferrer">American Heritage Dictionary</a></p><p>Ada juga Dauz, seorang penjual kopi yang punya cara melayani sederhana. Sebutkan apa yang kamu mau, lalu ia akan meracik dan menyajikannya. Semangat itu kami bawa ke Deuz. Tim menyampaikan apa yang dibutuhkan, lalu alurnya mengikuti kebutuhan pekerjaan tersebut.</p><p><em>Development Use</em> menggambarkan tujuan praktis proyek ini. Kami membuatnya untuk dipakai dalam pekerjaan pengembangan sehari-hari, dari membahas kebutuhan bisnis hingga membangun dan menguji hasilnya.</p><p>Kami merangkai cara kerja bersama Claude Code, inspirasi dokumentasi dari Kiro, dan fleksibilitas OpenSpec menjadi sebuah proyek. Dari <em>deus ex machina</em>, Dauz, dan <em>Development Use</em>, kami menamainya <strong>Deuz</strong>.</p>',15)])])}const g=e(r,[["render",t]]);export{p as __pageData,g as default};
